SELECT DISTINCT t1.ID, t1.ORDER_DATE, t1.STATUS, t1.TOTAL, t1.VERSION, t1.CUSTOMER_ID, t0.ID, t0.CREATED_AT, t0.EMAIL, t0.FIRST_NAME, t0.LAST_NAME, t0.CITY, t0.COUNTRY, t0.STREET, t0.ZIP, t2.ID, t2.LINE_NO, t2.QUANTITY, t2.UNIT_PRICE, t2.ORDER_ID, t2.PRODUCT_ID FROM CUSTOMER t0, ORDER_LINE t2, ORDERS t1 WHERE ((t1.ID BETWEEN ? AND ?) AND ((t0.ID = t1.CUSTOMER_ID) AND (t2.ORDER_ID = t1.ID))) ORDER BY t1.ID;

